# Review package: f4c21dd..HEAD

## Commits
61a7ce2 fix: require a letter or digit to start each word

## Files changed
 src/textstats.js       | 8 +++++---
 test/wordCount.test.js | 8 ++++++++
 2 files changed, 13 insertions(+), 3 deletions(-)

## Diff
diff --git a/src/textstats.js b/src/textstats.js
index 8f0bbd9..6a7e02a 100644
--- a/src/textstats.js
+++ b/src/textstats.js
@@ -1,16 +1,18 @@
-// A word is a run of letters or digits (any script), optionally joined to the
-// next run by a single apostrophe (straight or typographic) or hyphen. The
+// A word is a run of letters or digits (any script) that starts with a letter or
+// digit and may contain combining marks (accents, Devanagari vowel signs); a run
+// of marks alone, such as an emoji variation selector, is not a word. A run is
+// optionally joined to the next run by a single apostrophe (straight or typographic) or hyphen. The
 // joiners are only part of a word when letters or digits sit on both sides, so
 // a trailing "well-" or "dogs'" loses its joiner. Everything else, including
 // em dashes, periods and underscores, separates words.
-const WORD_PATTERN = /[\p{L}\p{M}\p{N}]+(?:['’-][\p{L}\p{M}\p{N}]+)*/gu;
+const WORD_PATTERN = /[\p{L}\p{N}][\p{L}\p{M}\p{N}]*(?:['’-][\p{L}\p{N}][\p{L}\p{M}\p{N}]*)*/gu;

 function assertText(fn, value) {
   if (typeof value !== 'string') {
     throw new TypeError(`${fn}: text must be a string, received ${value === null ? 'null' : typeof value}`);
   }
 }

 // Private: the single definition of "word" shared by every statistic below.
 function tokenize(text) {
   return text.match(WORD_PATTERN) ?? [];
diff --git a/test/wordCount.test.js b/test/wordCount.test.js
index 241da10..2260b03 100644
--- a/test/wordCount.test.js
+++ b/test/wordCount.test.js
@@ -141,10 +141,18 @@ test('keeps combining marks inside a word (Devanagari)', () => {
 });

 test('keeps a decomposed accent inside a word', () => {
   assert.equal(wordCount('nai\u0308ve cafe\u0301 au lait'), 4);
 });

 test('keeps combining marks after a joiner inside a word', () => {
   assert.equal(wordCount('re\u0301sume\u0301-style'), 1);
   assert.equal(wordCount('r\u00e9sum\u00e9-style'), 1);
 });
+
+test('a run of only combining marks is not a word', () => {
+  assert.equal(wordCount('I ❤️ NY'), 2); // heart + variation selector
+  assert.equal(wordCount('️'), 0); // lone variation selector
+  assert.equal(wordCount('́'), 0); // lone combining acute
+  assert.equal(wordCount('1️⃣'), 1); // keycap: digit start keeps its marks
+  assert.equal(wordCount('⃣'), 0); // lone keycap mark
+});

